    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
        'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
        sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

main {
    width: 100%;
}

.container {
    max-width: 500px;
    margin: 0 auto;
}

.form-wrapper {
    background: white;
    border-radius: 12px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.08);
    padding: 40px;
}

h1 {
    font-size: 28px;
    font-weight: 600;
    color: #1a202c;
    margin-bottom: 12px;
}

.intro-text {
    font-size: 14px;
    color: #718096;
    margin-bottom: 32px;
    line-height: 1.5;
}

form {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.checkbox-wrapper {
    display: flex;
    align-items: flex-start;
    gap: 12px;
}

input[type="checkbox"] {
    width: 20px;
    height: 20px;
    margin-top: 2px;
    cursor: pointer;
    accent-color: #3182ce;
    flex-shrink: 0;
}

input[type="checkbox"]:focus {
    outline: 2px solid #3182ce;
    outline-offset: 2px;
    border-radius: 4px;
}

input[type="checkbox"]:disabled {
    cursor: not-allowed;
    opacity: 0.5;
}

label {
    font-size: 15px;
    color: #2d3748;
    cursor: pointer;
    line-height: 1.5;
}

label a {
    color: #3182ce;
    text-decoration: none;
    border-bottom: 1px solid #3182ce;
}

label a:hover,
label a:focus {
    color: #2c5aa0;
}

label a:focus {
    outline: 2px solid #3182ce;
    outline-offset: 2px;
}

.required-marker {
    color: #e53e3e;
    font-weight: 600;
    margin-left: 2px;
}

.helper-text {
    font-size: 13px;
    color: #718096;
    line-height: 1.5;
    margin-left: 32px;
}

.error-message {
    font-size: 13px;
    color: #e53e3e;
    line-height: 1.5;
    margin-left: 32px;
    margin-top: 4px;
}

input[type="checkbox"][aria-invalid="true"] {
    accent-color: #e53e3e;
}

input[type="checkbox"][aria-invalid="true"]:focus {
    outline-color: #e53e3e;
}

.submit-button {
    background-color: #3182ce;
    color: white;
    border: none;
    padding: 12px 24px;
    font-size: 16px;
    font-weight: 500;
    border-radius: 6px;
    cursor: pointer;
    transition: background-color 0.2s ease, box-shadow 0.2s ease;
    padding: 14px 28px;
}

.submit-button:hover {
    background-color: #2c5aa0;
}

.submit-button:focus {
    outline: 2px solid #3182ce;
    outline-offset: 2px;
    box-shadow: 0 0 0 4px rgba(49, 130, 206, 0.1);
}

.submit-button:active {
    background-color: #2a5aa8;
    transform: scale(0.98);
}

.submit-button:disabled {
    background-color: #cbd5e0;
    cursor: not-allowed;
    color: #4a5568;
}

/* Responsive design */
@media (max-width: 480px) {
    .form-wrapper {
        padding: 24px;
    }

    h1 {
        font-size: 24px;
    }

    .submit-button {
        padding: 12px 20px;
        font-size: 15px;
    }
}

/* High contrast and forced-colors support */
@media (prefers-contrast: more) {
    body {
        background: #f0f0f0;
    }

    .form-wrapper {
        box-shadow: 0 0 0 2px #000;
    }

    input[type="checkbox"]:focus {
        outline-width: 3px;
    }

    .submit-button:focus {
        outline-width: 3px;
    }
}

@media (forced-colors: active) {
    input[type="checkbox"] {
        accent-color: CanvasText;
    }

    .submit-button {
        background-color: ButtonFace;
        color: ButtonText;
        border: 2px solid ButtonBorder;
    }

    .submit-button:focus {
        outline-width: 3px;
    }

    input[type="checkbox"]:focus,
    label a:focus,
    .submit-button:focus {
        outline: 3px solid;
    }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}
