const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

async function runAccessibilityTests() {
    const browser = await chromium.launch();
    const page = await browser.newPage();

    const htmlPath = path.resolve(__dirname, 'index.html');
    const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

    await page.setContent(htmlContent, { waitUntil: 'load' });

    // Inject axe-core from node_modules
    const axePath = require.resolve('axe-core');
    const axeSource = fs.readFileSync(axePath, 'utf-8');
    await page.addScriptTag({ content: axeSource });

    // Run axe
    const results = await page.evaluate(() => {
        return window.axe.run();
    });

    await browser.close();

    // Separate WCAG violations from best-practice
    const wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bestPracticeViolations = results.violations.filter(v => v.tags.includes('best-practice'));

    const report = {
        wcag: wcagViolations.map(v => ({
            id: v.id,
            impact: v.impact,
            description: v.description,
            targets: v.nodes.map(n => n.target)
        })),
        bestPractice: bestPracticeViolations.map(v => ({
            id: v.id,
            targets: v.nodes.map(n => n.target)
        }))
    };

    console.log(JSON.stringify(report, null, 2));
    process.exit(wcagViolations.length > 0 ? 1 : 0);
}

runAccessibilityTests().catch(err => {
    console.error('Test error:', err);
    process.exit(1);
});

