const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

async function runComprehensiveAccessibilityTests() {
    const browser = await chromium.launch();
    const page = await browser.newPage();

    const htmlPath = path.resolve(__dirname, 'index.html');
    const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

    await page.setContent(htmlContent, { waitUntil: 'load' });

    // Inject axe-core from node_modules
    const axePath = require.resolve('axe-core');
    const axeSource = fs.readFileSync(axePath, 'utf-8');
    await page.addScriptTag({ content: axeSource });

    console.log('\n=== Initial Page State ===');

    // Test 1: Initial state
    let results = await page.evaluate(() => {
        return window.axe.run();
    });

    let wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
    let bestPracticeViolations = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log('WCAG Violations:', wcagViolations.length);
    console.log('Best Practice Violations:', bestPracticeViolations.length);

    // Test 2: Try to submit without checking checkbox
    console.log('\n=== Submit Without Checking Checkbox ===');
    await page.click('button[type="submit"]');
    await page.waitForTimeout(100);

    // Check if error is shown
    const errorHidden = await page.evaluate(() => {
        const error = document.getElementById('agree-error');
        return error.hasAttribute('hidden');
    });
    console.log('Error message hidden:', errorHidden);

    const ariaInvalid = await page.evaluate(() => {
        const checkbox = document.getElementById('agree-terms');
        return checkbox.getAttribute('aria-invalid');
    });
    console.log('Checkbox aria-invalid:', ariaInvalid);

    // Test 3: After error state, check for violations
    console.log('\n=== After Error Display ===');
    results = await page.evaluate(() => {
        return window.axe.run();
    });

    wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
    bestPracticeViolations = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log('WCAG Violations:', wcagViolations.length);
    console.log('Best Practice Violations:', bestPracticeViolations.length);

    // Test 4: Check checkbox and verify error clears
    console.log('\n=== After Checking Checkbox ===');
    await page.click('input[type="checkbox"]');
    await page.waitForTimeout(100);

    const errorHiddenAfterCheck = await page.evaluate(() => {
        const error = document.getElementById('agree-error');
        return error.hasAttribute('hidden');
    });
    console.log('Error message hidden:', errorHiddenAfterCheck);

    const ariaInvalidAfterCheck = await page.evaluate(() => {
        const checkbox = document.getElementById('agree-terms');
        return checkbox.getAttribute('aria-invalid');
    });
    console.log('Checkbox aria-invalid:', ariaInvalidAfterCheck);

    results = await page.evaluate(() => {
        return window.axe.run();
    });

    wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
    bestPracticeViolations = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log('WCAG Violations:', wcagViolations.length);
    console.log('Best Practice Violations:', bestPracticeViolations.length);

    // Final report
    console.log('\n=== Final Report ===');
    if (wcagViolations.length > 0) {
        console.log('WCAG Issues Found:');
        wcagViolations.forEach(v => {
            console.log(`  - ${v.id} (${v.impact}): ${v.nodes.map(n => n.target).join(', ')}`);
        });
    } else {
        console.log('✓ No WCAG violations found');
    }

    if (bestPracticeViolations.length > 0) {
        console.log('Best Practice Issues:');
        bestPracticeViolations.forEach(v => {
            console.log(`  - ${v.id}: ${v.nodes.map(n => n.target).join(', ')}`);
        });
    } else {
        console.log('✓ No best-practice violations found');
    }

    await browser.close();
    process.exit(wcagViolations.length > 0 ? 1 : 0);
}

runComprehensiveAccessibilityTests().catch(err => {
    console.error('Test error:', err);
    process.exit(1);
});

