        const error = document.getElementById('agree-error');
        const checkbox = document.getElementById('agree-terms');
        if (!error || !checkbox) return { error: 'missing elements' };
        return {
            errorHidden: error.hasAttribute('hidden'),
            checkboxChecked: checkbox.checked,
            ariaInvalid: checkbox.getAttribute('aria-invalid')
        };
    });
    console.log('After check state:', afterCheckState);

    results = await page.evaluate(() => {
        return window.axe.run();
    });

    wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
    bestPracticeViolations = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log('WCAG Violations:', wcagViolations.length);
    console.log('Best Practice Violations:', bestPracticeViolations.length);

