    console.log('\n=== Final Report ===');
    if (wcagViolations.length > 0) {
        console.log('WCAG Issues Found:');
        wcagViolations.forEach(v => {
            console.log(`  - ${v.id} (${v.impact}): ${v.nodes.map(n => n.target).join(', ')}`);
        });
